import { expect, test } from "bun:test";
import { splitCharge } from "../../src/fees/split";

test("an even charge splits into equal shares", () => {
  expect(splitCharge(2000, 2)).toEqual([1000, 1000]);
});

test("one borrower pays the whole charge", () => {
  expect(splitCharge(3333, 1)).toEqual([3333]);
});

test("leftover cents go one each to the first borrowers", () => {
  expect(splitCharge(3333, 2)).toEqual([1667, 1666]);
  expect(splitCharge(1000, 3)).toEqual([334, 333, 333]);
  expect(splitCharge(5, 4)).toEqual([2, 1, 1, 1]);
});

test("the shares add up to exactly the charge", () => {
  for (const total of [0, 1, 99, 3333, 10001]) {
    for (const ways of [1, 2, 3, 4, 7]) {
      const sum = splitCharge(total, ways).reduce((a, b) => a + b, 0);
      expect(sum).toBe(total);
    }
  }
});

test("no share differs from another by more than one cent", () => {
  for (const total of [0, 1, 99, 3333, 10001]) {
    for (const ways of [1, 2, 3, 4, 7]) {
      const shares = splitCharge(total, ways);
      expect(Math.max(...shares) - Math.min(...shares)).toBeLessThanOrEqual(1);
    }
  }
});

test("a charge that divides evenly gives every borrower the same share", () => {
  expect(splitCharge(900, 3)).toEqual([300, 300, 300]);
});

test("a negative charge is refused", () => {
  expect(() => splitCharge(-1, 2)).toThrow();
});

